import{_ as a,o,c as t,a2 as r}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_01_three_mode_boundary.png",c="/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_02_autonomous_actions.png",i="/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_03_fixed_path_update.png",d="/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_04_remote_control.png",n="/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_05_services_lifecycle.png",h="/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_06_monitor_recovery.png",g=JSON.parse('{"title":"一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？","description":"同一台物流机器人，为什么既能让人用键盘接管，又能自主绕障规划，还能沿上游给定的固定路线巡迹？","frontmatter":{"title":"一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？","description":"同一台物流机器人，为什么既能让人用键盘接管，又能自主绕障规划，还能沿上游给定的固定路线巡迹？","date":"2026-07-28","section":"一 · 架构与启动","readingTime":19,"source":"2026-07-28/nav2_regulated_modules_three_mode_interfaces_dataflow.md","status":"published","cover":"/article-assets/2026-07-28/nav2_regulated_modules_01_three_mode_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-modules-three-mode-interfaces-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？"}],["meta",{"property":"og:description","content":"同一台物流机器人，为什么既能让人用键盘接管，又能自主绕障规划，还能沿上游给定的固定路线巡迹？"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-modules-three-mode-interfaces-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_01_three_mode_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-28"}],["meta",{"name":"twitter:title","content":"一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？"}],["meta",{"name":"twitter:description","content":"同一台物流机器人，为什么既能让人用键盘接管，又能自主绕障规划，还能沿上游给定的固定路线巡迹？"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-28/nav2_regulated_modules_01_three_mode_boundary.png"}]],"prev":{"text":"一个节点失联，为什么整套 Nav2 都要停？逐函数拆解 Lifecycle Manager","link":"/nav2/nav2-lifecycle-manager-source-walkthrough"},"next":{"text":"Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree","link":"/nav2/navigation2-overview-design-analysis"}},"headers":[],"relativePath":"nav2/nav2-regulated-modules-three-mode-interfaces-dataflow.md","filePath":"nav2/nav2-regulated-modules-three-mode-interfaces-dataflow.md","lastUpdated":null}'),s={name:"nav2/nav2-regulated-modules-three-mode-interfaces-dataflow.md"};function p(_,e,u,m,v,P){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="一个底盘-三种大脑-nav2-regulated-modules-如何用-action-与-service-串起整套-nav2" tabindex="-1">一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？ <a class="header-anchor" href="#一个底盘-三种大脑-nav2-regulated-modules-如何用-action-与-service-串起整套-nav2" aria-label="Permalink to &quot;一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？&quot;">​</a></h1><p>同一台物流机器人，为什么既能让人用键盘接管，又能自主绕障规划，还能沿上游给定的固定路线巡迹？</p><p>关键不在于复制三套导航栈，而在于明确三件事：任务由谁接收，路径由谁生成，底盘命令最终归谁所有。<code>nav2_regulated_modules</code> 正是在这三条边界上重组 Nav2。它没有使用 Behavior Tree 编排任务，而是让一个 Lifecycle 状态机直接连接 Planner、Smoother 和 Controller 的标准 Action，并在 Launch 层把遥控、自主规划、固定路径做成互斥分支。</p><p>本文以 <code>2026-07-28</code> 的当前工作树为准。包内有 51 个生产入口，但这里不按函数机械排列，而是按照所有实际模块、Action、Service、Topic、TF 和回调接力关系，还原一条命令从入口到 <code>/control_to_uart</code> 的完整数据流。</p><h2 id="一、这个包真正解决的是什么" tabindex="-1">一、这个包真正解决的是什么 <a class="header-anchor" href="#一、这个包真正解决的是什么" aria-label="Permalink to &quot;一、这个包真正解决的是什么&quot;">​</a></h2><h3 id="_1-1-它不是新的规划器或控制器" tabindex="-1">1.1 它不是新的规划器或控制器 <a class="header-anchor" href="#_1-1-它不是新的规划器或控制器" aria-label="Permalink to &quot;1.1 它不是新的规划器或控制器&quot;">​</a></h3><p><code>nav2_regulated_modules</code> 不实现 A*、DWB、MPPI 或 Pure Pursuit。它保留标准 Nav2 服务器，把已有算法作为插件继续运行：</p><ul><li>Planner Server 加载 NavFn、Smac2D、SmacHybrid、SmacLattice 和 ThetaStar。</li><li>Smoother Server 加载 <code>simple_smoother</code>。</li><li>Controller Server 同时加载 DWB、RPP、MPPI、Graceful Controller 和 Rotation Shim。</li><li>Velocity Smoother 对控制器输出做闭环速度限制。</li></ul><p>本包新增的是“谁在什么时候调用谁”。<code>regulated_navigator</code> 取代 BT Navigator，成为导航任务的单一状态所有者。</p><h3 id="_1-2-三种模式共享一条安全边界" tabindex="-1">1.2 三种模式共享一条安全边界 <a class="header-anchor" href="#_1-2-三种模式共享一条安全边界" aria-label="Permalink to &quot;1.2 三种模式共享一条安全边界&quot;">​</a></h3><p>启动参数 <code>operation_mode</code> 只允许三个值：</p><ul><li><code>remote</code>：人直接控制底盘。</li><li><code>autonomous</code>：系统计算路径、平滑路径并闭环跟踪。</li><li><code>fixed_path</code>：上游直接给出完整 Path，系统不做全局规划。</li></ul><p>三种模式都必须满足同一条硬约束：任意时刻 <code>/control_to_uart</code> 只能有一个发布者。遥控模式由键盘节点发布；另外两种模式由 <code>controlpub</code> 发布。</p><h3 id="_1-3-源码边界必须先说清" tabindex="-1">1.3 源码边界必须先说清 <a class="header-anchor" href="#_1-3-源码边界必须先说清" aria-label="Permalink to &quot;1.3 源码边界必须先说清&quot;">​</a></h3><p>本文描述的是当前 <code>navigation2</code> 文件的真实行为，不依赖某个 Git 提交号作为阅读前提。</p><p><img src="'+l+'" alt="三模式启动边界"></p><h2 id="二、launch-如何切开三条互斥链" tabindex="-1">二、Launch 如何切开三条互斥链 <a class="header-anchor" href="#二、launch-如何切开三条互斥链" aria-label="Permalink to &quot;二、Launch 如何切开三条互斥链&quot;">​</a></h2><h3 id="_2-1-generate-launch-description-是总路由器" tabindex="-1">2.1 <code>generate_launch_description()</code> 是总路由器 <a class="header-anchor" href="#_2-1-generate-launch-description-是总路由器" aria-label="Permalink to &quot;2.1 `generate_launch_description()` 是总路由器&quot;">​</a></h3><p>统一 Launch 读取 namespace、地图、参数文件、RViz、Composition、重启、日志、模式和键盘终端等参数。真正决定系统形态的是两个条件：</p><ul><li><code>is_remote</code>：<code>operation_mode == remote</code>。</li><li><code>is_navigation</code>：<code>operation_mode != remote</code>。</li></ul><p>因此遥控与导航组在进程层已经互斥，不需要等节点启动后再竞争控制权。</p><h3 id="_2-2-remote-只启动一个业务节点" tabindex="-1">2.2 <code>remote</code> 只启动一个业务节点 <a class="header-anchor" href="#_2-2-remote-只启动一个业务节点" aria-label="Permalink to &quot;2.2 `remote` 只启动一个业务节点&quot;">​</a></h3><p>遥控分支只创建 <code>myagv_keyboard_control</code>。它不会启动 Map Server、Planner、Controller、Smoother、Velocity Smoother、<code>regulated_navigator</code>、Lifecycle Manager 或 <code>controlpub</code>。</p><p>这种设计的意义不是省资源，而是从 ROS 图上消除额外的底盘命令源。</p><h3 id="_2-3-两种导航模式共享同一组进程" tabindex="-1">2.3 两种导航模式共享同一组进程 <a class="header-anchor" href="#_2-3-两种导航模式共享同一组进程" aria-label="Permalink to &quot;2.3 两种导航模式共享同一组进程&quot;">​</a></h3><p><code>autonomous</code> 和 <code>fixed_path</code> 都进入 <code>navigation_group</code>，共同启动：</p><ul><li>RViz。</li><li>Map Server 与地图 Lifecycle Manager。</li><li>Planner Server。</li><li>Controller Server。</li><li>Smoother Server。</li><li>Velocity Smoother。</li><li><code>regulated_navigator</code>。</li><li><code>controlpub</code>。</li><li>规控 Lifecycle Manager。</li></ul><p>固定路径模式仍会启动 Planner 和 Smoother 进程，但 <code>regulated_navigator</code> 不向它们发送业务 Action Goal。这是“服务器存在”和“业务链调用”之间的重要区别。</p><h3 id="_2-4-进程模式与-composition-模式" tabindex="-1">2.4 进程模式与 Composition 模式 <a class="header-anchor" href="#_2-4-进程模式与-composition-模式" aria-label="Permalink to &quot;2.4 进程模式与 Composition 模式&quot;">​</a></h3><p><code>use_composition=false</code> 时，每个标准 Nav2 Server 都是独立进程。<code>use_composition=true</code> 时，Planner、Controller、Smoother、Velocity Smoother 和 Lifecycle Manager 被加载到指定容器，自定义 Navigator 与 <code>controlpub</code> 仍是独立进程。</p><p>当前 Launch 只执行 <code>LoadComposableNodes</code>，不会创建 Component Container。因此开启 Composition 前，外部必须已经启动名称匹配的容器。</p><h2 id="三、十二类运行模块分别负责什么" tabindex="-1">三、十二类运行模块分别负责什么 <a class="header-anchor" href="#三、十二类运行模块分别负责什么" aria-label="Permalink to &quot;三、十二类运行模块分别负责什么&quot;">​</a></h2><h3 id="_3-1-regulated-navigator-任务与状态所有者" tabindex="-1">3.1 <code>regulated_navigator</code>：任务与状态所有者 <a class="header-anchor" href="#_3-1-regulated-navigator-任务与状态所有者" aria-label="Permalink to &quot;3.1 `regulated_navigator`：任务与状态所有者&quot;">​</a></h3><p>它对外是 <code>NavigateToPose</code> 和 <code>NavigateThroughPoses</code> 的 Action Server，对内是 ComputePath、SmoothPath 和 FollowPath 的 Action Client，同时还是双 Costmap 清图 Service 的客户端。</p><p>它保存任务类型、状态、目标、路径、反馈、恢复次数以及异步回调代次，是全链唯一可以决定“继续、抢占、恢复、成功或失败”的模块。</p><h3 id="_3-2-planner-server-与-global-costmap" tabindex="-1">3.2 Planner Server 与 Global Costmap <a class="header-anchor" href="#_3-2-planner-server-与-global-costmap" aria-label="Permalink to &quot;3.2 Planner Server 与 Global Costmap&quot;">​</a></h3><p>Planner Server 接收 <code>ComputePathToPose</code> 或 <code>ComputePathThroughPoses</code>，读取 TF 和 Global Costmap，调用选中的规划插件并返回 <code>nav_msgs/Path</code>。</p><p>它还发布 <code>/plan</code>，并提供 <code>is_path_valid</code> Service。当前自研 Navigator 没有调用 <code>is_path_valid</code>，而是直接使用规划 Action 的 Result。</p><h3 id="_3-3-smoother-server-与-controller-server" tabindex="-1">3.3 Smoother Server 与 Controller Server <a class="header-anchor" href="#_3-3-smoother-server-与-controller-server" aria-label="Permalink to &quot;3.3 Smoother Server 与 Controller Server&quot;">​</a></h3><p>Smoother Server 接收 <code>SmoothPath</code>，把原始 Path 交给 <code>simple_smoother</code>，输出平滑路径并发布 <code>/plan_smoothed</code>。</p><p>Controller Server 接收 <code>FollowPath</code>，结合 Local Costmap、TF、当前速度、Goal Checker 和 Progress Checker 计算 <code>Twist</code>。Launch 把它原本的 <code>cmd_vel</code> 输出重映射成 <code>cmd_vel_nav</code>。</p><h3 id="_3-4-velocity-smoother-与-controlpub" tabindex="-1">3.4 Velocity Smoother 与 <code>controlpub</code> <a class="header-anchor" href="#_3-4-velocity-smoother-与-controlpub" aria-label="Permalink to &quot;3.4 Velocity Smoother 与 `controlpub`&quot;">​</a></h3><p>Velocity Smoother 订阅 <code>cmd_vel_nav</code>，以 <code>20 Hz</code> 执行速度、加速度、减速度和超时约束。当前配置是 <code>CLOSED_LOOP</code>，每次平滑以 <code>/odometry</code> 的实测速度为起点，输出 Topic 被重映射为 <code>/cmd_vel</code>。</p><p><code>controlpub</code> 订阅 <code>/cmd_vel</code>，把 <code>linear.x</code> 和 <code>angular.z</code> 写入 <code>ControlRes.v</code> 与 <code>ControlRes.w</code>，把升降和上肢旋转字段清零，再发布 <code>/control_to_uart</code>。</p><h3 id="_3-5-map-server、costmap-与-lifecycle-manager" tabindex="-1">3.5 Map Server、Costmap 与 Lifecycle Manager <a class="header-anchor" href="#_3-5-map-server、costmap-与-lifecycle-manager" aria-label="Permalink to &quot;3.5 Map Server、Costmap 与 Lifecycle Manager&quot;">​</a></h3><p>Map Server 从 YAML 和 PGM 加载静态地图，发布 <code>/map</code>。Global Costmap 把静态地图、雷达和 Inflation 合成为规划代价；Local Costmap 使用滚动窗口、实时雷达和 Footprint 支撑局部控制。</p><p>两个 Lifecycle Manager 分开管理地图链和规控链，避免 Planner 等待地图时出现无序激活。</p><h3 id="_3-6-键盘节点、rviz-与外部数据源" tabindex="-1">3.6 键盘节点、RViz 与外部数据源 <a class="header-anchor" href="#_3-6-键盘节点、rviz-与外部数据源" aria-label="Permalink to &quot;3.6 键盘节点、RViz 与外部数据源&quot;">​</a></h3><p>键盘节点只属于 <code>remote</code>。RViz 只属于导航组，可展示地图、雷达、全局／局部代价地图和路径，也可通过 Goal Tool 或 Navigation 2 面板产生任务。</p><p>外部系统必须提供：</p><ul><li><code>/c200_lidar_node/scan</code>。</li><li><code>/odometry</code>。</li><li>可查询的 <code>map → base_link</code> TF。</li><li>真正消费 <code>/control_to_uart</code> 的底盘通信节点。</li></ul><h2 id="四、lifecycle-如何把接口从-存在-变成-可用" tabindex="-1">四、Lifecycle 如何把接口从“存在”变成“可用” <a class="header-anchor" href="#四、lifecycle-如何把接口从-存在-变成-可用" aria-label="Permalink to &quot;四、Lifecycle 如何把接口从“存在”变成“可用”&quot;">​</a></h2><h3 id="_4-1-构造阶段只声明参数" tabindex="-1">4.1 构造阶段只声明参数 <a class="header-anchor" href="#_4-1-构造阶段只声明参数" aria-label="Permalink to &quot;4.1 构造阶段只声明参数&quot;">​</a></h3><p><code>RegulatedNavigator</code> 构造函数声明坐标系、模式、Action 名称、插件 ID、超时、反馈频率、重规划、定位监控、恢复和停车 Topic 等参数。构造时不等待任何外部服务器，也不接收任务。</p><h3 id="_4-2-on-configure-创建全部通信接口" tabindex="-1">4.2 <code>on_configure()</code> 创建全部通信接口 <a class="header-anchor" href="#_4-2-on-configure-创建全部通信接口" aria-label="Permalink to &quot;4.2 `on_configure()` 创建全部通信接口&quot;">​</a></h3><p>配置回调读取参数并完成四类动作：</p><ul><li>配置 <code>PlanningModule</code> 与 <code>ControlModule</code>。</li><li>创建四个下游 Action Client。</li><li>创建两个外层 Action Server、两个任务订阅和停车发布器。</li><li>创建 TF Buffer、TF Listener、反馈 Timer 与监控 Timer。</li></ul><p>固定路径订阅只在 <code>operation_mode == fixed_path</code> 时创建。<code>goal_pose</code> 订阅始终创建，但非自主模式的回调会明确忽略输入。</p><h3 id="_4-3-on-activate-才开放任务" tabindex="-1">4.3 <code>on_activate()</code> 才开放任务 <a class="header-anchor" href="#_4-3-on-activate-才开放任务" aria-label="Permalink to &quot;4.3 `on_activate()` 才开放任务&quot;">​</a></h3><p>激活回调设置 <code>active_ = true</code> 并创建 Lifecycle Bond。Goal 回调会检查 <code>active_</code>，因此配置完成但尚未激活的节点不会接收导航任务。</p><h3 id="_4-4-停用、清理与关闭" tabindex="-1">4.4 停用、清理与关闭 <a class="header-anchor" href="#_4-4-停用、清理与关闭" aria-label="Permalink to &quot;4.4 停用、清理与关闭&quot;">​</a></h3><p><code>on_deactivate()</code> 先关闭业务入口，再取消任务、发布停车命令并销毁 Bond。</p><p><code>on_cleanup()</code> 进一步释放 Action、Service、Topic、Timer 和 TF 对象，回到未配置状态。</p><p><code>on_shutdown()</code> 在进程退出前再次调用任务取消逻辑，作为最后一道收口。</p><h2 id="五、外层任务如何进入状态机" tabindex="-1">五、外层任务如何进入状态机 <a class="header-anchor" href="#五、外层任务如何进入状态机" aria-label="Permalink to &quot;五、外层任务如何进入状态机&quot;">​</a></h2><h3 id="_5-1-navigatetopose-的三个回调" tabindex="-1">5.1 <code>NavigateToPose</code> 的三个回调 <a class="header-anchor" href="#_5-1-navigatetopose-的三个回调" aria-label="Permalink to &quot;5.1 `NavigateToPose` 的三个回调&quot;">​</a></h3><p>单点 Action Server 为每个 Goal 安装 Goal、Cancel 和 Accepted 回调：</p><ul><li>Goal 回调检查必须处于自主模式、节点已激活、Pose 有效，并拒绝携带 Behavior Tree XML 的请求。</li><li>Cancel 回调只为当前活动句柄设置 <code>cancel_requested_</code>，真正取消由监控 Timer 统一执行。</li><li>Accepted 回调抢占旧任务，保存新终点，增加任务代次，再调用 <code>startPlanning(false)</code>。</li></ul><h3 id="_5-2-navigatethroughposes-的区别" tabindex="-1">5.2 <code>NavigateThroughPoses</code> 的区别 <a class="header-anchor" href="#_5-2-navigatethroughposes-的区别" aria-label="Permalink to &quot;5.2 `NavigateThroughPoses` 的区别&quot;">​</a></h3><p>多点 Goal 会逐个检查 Pose，并拒绝空数组。Accepted 回调保存完整目标序列，把最后一个 Pose 作为最终终点。</p><p>监控期间，机器人进入 <code>passed_goal_radius</code> 后，已通过的前置目标会从数组中移除。反馈里的 <code>number_of_poses_remaining</code> 因而会逐步减少。</p><h3 id="_5-3-goal-pose-是无-action-句柄的兼容入口" tabindex="-1">5.3 <code>goal_pose</code> 是无 Action 句柄的兼容入口 <a class="header-anchor" href="#_5-3-goal-pose-是无-action-句柄的兼容入口" aria-label="Permalink to &quot;5.3 `goal_pose` 是无 Action 句柄的兼容入口&quot;">​</a></h3><p><code>onTopicGoal()</code> 接收 <code>PoseStamped</code>，同样要求自主模式、active 和有效 Pose。它会抢占旧任务并启动单点规划，但没有外层 Action Goal Handle，因此没有标准 Action Result 和 Feedback。</p><p>这条入口适合 RViz Goal Tool 或简单上游节点，不适合需要严格结果语义的任务调度器。</p><h3 id="_5-4-新任务如何隔离旧回调" tabindex="-1">5.4 新任务如何隔离旧回调 <a class="header-anchor" href="#_5-4-新任务如何隔离旧回调" aria-label="Permalink to &quot;5.4 新任务如何隔离旧回调&quot;">​</a></h3><p>每个任务拥有 <code>generation</code>，每次规划和控制又各有独立 <code>sequence</code>。异步 Goal Response、Feedback 和 Result 只有同时匹配当前任务代次与当前请求序号，才允许修改状态。</p><p>旧 Goal 即使晚到，也不能用旧路径覆盖新任务。</p><h2 id="六、自主模式的六个-action-端点" tabindex="-1">六、自主模式的六个 Action 端点 <a class="header-anchor" href="#六、自主模式的六个-action-端点" aria-label="Permalink to &quot;六、自主模式的六个 Action 端点&quot;">​</a></h2><h3 id="_6-1-外层两个-action-只负责表达任务" tabindex="-1">6.1 外层两个 Action 只负责表达任务 <a class="header-anchor" href="#_6-1-外层两个-action-只负责表达任务" aria-label="Permalink to &quot;6.1 外层两个 Action 只负责表达任务&quot;">​</a></h3><p><code>navigate_to_pose</code> 与 <code>navigate_through_poses</code> 是对上层任务系统的稳定接口。它们不直接计算路径，只负责接收目标、取消请求、反馈和最终结果。</p><h3 id="_6-2-planner-的两个-action-负责产生-path" tabindex="-1">6.2 Planner 的两个 Action 负责产生 Path <a class="header-anchor" href="#_6-2-planner-的两个-action-负责产生-path" aria-label="Permalink to &quot;6.2 Planner 的两个 Action 负责产生 Path&quot;">​</a></h3><p><code>startPlanning()</code> 根据任务类型选择：</p><ul><li>单点任务调用 <code>compute_path_to_pose</code>。</li><li>多点任务调用 <code>compute_path_through_poses</code>。</li></ul><p>两种 Goal 都设置 <code>use_start=false</code>，表示 Planner Server 通过 TF 获取当前机器人起点。规划插件 ID 来自 <code>PlanningModule::plannerId()</code>。</p><h3 id="_6-3-selected-planner-可能覆盖-action-字段" tabindex="-1">6.3 <code>selected_planner</code> 可能覆盖 Action 字段 <a class="header-anchor" href="#_6-3-selected-planner-可能覆盖-action-字段" aria-label="Permalink to &quot;6.3 `selected_planner` 可能覆盖 Action 字段&quot;">​</a></h3><p>当前 Navigator 的 <code>planner_id</code> 与 Planner Server 的 <code>selected_planner</code> 都是 <code>GridBasedAstar</code>。</p><p>Planner Server 的 <code>selected_planner</code> 非空时，会覆盖 Action Goal 中的 <code>planner_id</code>。因此切换算法时不能只改 Navigator 参数，否则日志会提示 Action 请求与服务器强制选择不一致。</p><h3 id="_6-4-smoothpath-是可选中间层" tabindex="-1">6.4 SmoothPath 是可选中间层 <a class="header-anchor" href="#_6-4-smoothpath-是可选中间层" aria-label="Permalink to &quot;6.4 SmoothPath 是可选中间层&quot;">​</a></h3><p>规划成功后，<code>onPathReady()</code> 根据 <code>use_smoother</code> 分流。启用时构造 <code>SmoothPath::Goal</code>，写入原始 Path、平滑插件 ID、最长平滑时间和碰撞检查开关。</p><p>平滑成功则发送平滑 Path；Goal 被拒绝、Result 失败或返回空 Path 时，系统回退原始规划 Path，而不是直接让导航失败。</p><h3 id="_6-5-followpath-把-path-变成控制闭环" tabindex="-1">6.5 FollowPath 把 Path 变成控制闭环 <a class="header-anchor" href="#_6-5-followpath-把-path-变成控制闭环" aria-label="Permalink to &quot;6.5 FollowPath 把 Path 变成控制闭环&quot;">​</a></h3><p><code>sendFollowPath()</code> 写入 Path、<code>controller_id</code> 和 <code>goal_checker_id</code>。Controller Server 接收后设置当前全局路径，按控制频率生成速度。</p><p>FollowPath Feedback 中的 <code>distance_to_goal</code> 与 <code>speed</code> 被 Navigator 缓存，用于外层剩余距离和 ETA。Result 成功触发 <code>succeedTask()</code>；非取消状态下失败则进入恢复。</p><h3 id="_6-6-周期重规划不会停止控制" tabindex="-1">6.6 周期重规划不会停止控制 <a class="header-anchor" href="#_6-6-周期重规划不会停止控制" aria-label="Permalink to &quot;6.6 周期重规划不会停止控制&quot;">​</a></h3><p>控制状态下，监控 Timer 按 <code>replan_frequency=1.0 Hz</code> 再次调用 Planner。更新规划失败且旧 FollowPath 仍有效时，只要连续失败没有达到上限，Controller 会继续沿旧路径运动。</p><p>新 Path 成功后会提交新的 FollowPath Goal。Controller Server 接受 Pending Goal 后调用 <code>setPlannerPath()</code> 更新当前路径。</p><p><img src="'+c+'" alt="自主模式 Action 闭环"></p><h2 id="七、固定路径为什么不是-另一种规划" tabindex="-1">七、固定路径为什么不是“另一种规划” <a class="header-anchor" href="#七、固定路径为什么不是-另一种规划" aria-label="Permalink to &quot;七、固定路径为什么不是“另一种规划”&quot;">​</a></h2><h3 id="_7-1-输入是一条完整-path" tabindex="-1">7.1 输入是一条完整 Path <a class="header-anchor" href="#_7-1-输入是一条完整-path" aria-label="Permalink to &quot;7.1 输入是一条完整 Path&quot;">​</a></h3><p>固定路径入口是 <code>/fixed_path</code>，消息类型为 <code>nav_msgs/msg/Path</code>，QoS 为可靠、深度一。每次消息都代表完整替换路径，不是增量补丁，也不是几个等待系统自动连线的稀疏航点。</p><h3 id="_7-2-preparefixedpath-只做契约处理" tabindex="-1">7.2 <code>prepareFixedPath()</code> 只做契约处理 <a class="header-anchor" href="#_7-2-preparefixedpath-只做契约处理" aria-label="Permalink to &quot;7.2 `prepareFixedPath()` 只做契约处理&quot;">​</a></h3><p>它检查 Path 至少有两个 Pose、Path frame 不为空、位置为有限数、四元数范数有效。随后逐 Pose 使用 TF Buffer 变换到 <code>global_frame</code>，统一时间戳并生成新的 Path。</p><p>这里没有栅格搜索、绕障或路径拓扑修改。上游给出的线经过障碍时，系统不会调用 Planner 自动绕开。</p><h3 id="_7-3-首次-path-创建任务" tabindex="-1">7.3 首次 Path 创建任务 <a class="header-anchor" href="#_7-3-首次-path-创建任务" aria-label="Permalink to &quot;7.3 首次 Path 创建任务&quot;">​</a></h3><p>首次收到有效 Path 时会创建 <code>TaskType::FIXED_PATH</code>，保存最后一个 Pose 作为终点，保存整条 Path 作为恢复数据，然后直接调用 FollowPath。</p><p>Planner Server 和 Smoother Server 虽然进程存在，但没有收到 Goal。</p><h3 id="_7-4-后续-path-通过-followpath-抢占更新" tabindex="-1">7.4 后续 Path 通过 FollowPath 抢占更新 <a class="header-anchor" href="#_7-4-后续-path-通过-followpath-抢占更新" aria-label="Permalink to &quot;7.4 后续 Path 通过 FollowPath 抢占更新&quot;">​</a></h3><p>收到更新 Path 时，Navigator 不主动取消旧 FollowPath，而是提交新 Goal。Controller Server 接受 Pending Goal 后替换当前路径，控制进程不必重启。</p><p>这种方式保留 Local Costmap、碰撞检查、Progress Checker、Goal Checker 和速度平滑，只旁路全局路径生成。</p><h3 id="_7-5-定位丢失时只更新缓存" tabindex="-1">7.5 定位丢失时只更新缓存 <a class="header-anchor" href="#_7-5-定位丢失时只更新缓存" aria-label="Permalink to &quot;7.5 定位丢失时只更新缓存&quot;">​</a></h3><p>状态为 <code>LOCALIZATION_LOST</code> 时，新 Path 会被校验并保存，但不会立即下发。定位连续稳定后，<code>resumeCurrentTask()</code> 重发最新完整 Path。</p><p><img src="'+i+'" alt="固定路径更新链"></p><h2 id="八、controller-之后还有哪些数据变换" tabindex="-1">八、Controller 之后还有哪些数据变换 <a class="header-anchor" href="#八、controller-之后还有哪些数据变换" aria-label="Permalink to &quot;八、Controller 之后还有哪些数据变换&quot;">​</a></h2><h3 id="_8-1-local-costmap-是控制器的实时环境" tabindex="-1">8.1 Local Costmap 是控制器的实时环境 <a class="header-anchor" href="#_8-1-local-costmap-是控制器的实时环境" aria-label="Permalink to &quot;8.1 Local Costmap 是控制器的实时环境&quot;">​</a></h3><p>Controller Server 内部拥有 Local Costmap，当前使用 Voxel Layer 和 Inflation Layer。活动传感器 Topic 是 <code>/c200_lidar_node/scan</code>，机器人 Footprint 参与碰撞语义。</p><p>固定 Path 不经过全局规划，并不等于无安全控制；局部控制器仍会根据 Local Costmap 拒绝危险速度。</p><h3 id="_8-2-控制器插件由-followpath-goal-选择" tabindex="-1">8.2 控制器插件由 FollowPath Goal 选择 <a class="header-anchor" href="#_8-2-控制器插件由-followpath-goal-选择" aria-label="Permalink to &quot;8.2 控制器插件由 FollowPath Goal 选择&quot;">​</a></h3><p>当前 <code>controller_id</code> 为 <code>DWB</code>，Controller Server 同时加载 RPP、MPPI、Graceful Controller 和 Rotation Shim。Goal 中的 ID 决定本次跟踪使用哪个插件。</p><p><code>goal_checker_id</code> 当前为 <code>general_goal_checker</code>，负责判断位置与航向是否到达。</p><h3 id="_8-3-两套-progress-checker-同时存在" tabindex="-1">8.3 两套 Progress Checker 同时存在 <a class="header-anchor" href="#_8-3-两套-progress-checker-同时存在" aria-label="Permalink to &quot;8.3 两套 Progress Checker 同时存在&quot;">​</a></h3><p>Controller Server 内部的 <code>SimpleProgressChecker</code> 要求规定时间内移动规定距离。</p><p>Navigator 还用 <code>map → base_link</code> 自己做一层进展检查：累计平移达到 <code>0.1 m</code> 才刷新时间，连续 <code>10 s</code> 无进展则触发恢复。两层检查任何一层失败，都可能让 FollowPath 或外层任务进入失败链。</p><h3 id="_8-4-速度平滑是最终运动限幅" tabindex="-1">8.4 速度平滑是最终运动限幅 <a class="header-anchor" href="#_8-4-速度平滑是最终运动限幅" aria-label="Permalink to &quot;8.4 速度平滑是最终运动限幅&quot;">​</a></h3><p>Controller 的 <code>cmd_vel</code> 被重映射为 <code>cmd_vel_nav</code>。Velocity Smoother 使用 <code>/odometry</code> 闭环反馈，按三轴最大速度 <code>[0.26, 0.0, 1.0]</code>、加速度和减速度约束输出 <code>/cmd_vel</code>。</p><p>Navigator 的 <code>stopRobot()</code> 也向 <code>cmd_vel_nav</code> 发布三次零 Twist，因此停车命令仍会经过同一平滑和底盘转换链。</p><h3 id="_8-5-controlpub-只转换消息-不做控制" tabindex="-1">8.5 <code>controlpub</code> 只转换消息，不做控制 <a class="header-anchor" href="#_8-5-controlpub-只转换消息-不做控制" aria-label="Permalink to &quot;8.5 `controlpub` 只转换消息，不做控制&quot;">​</a></h3><p><code>controlpub</code> 不计算速度，也不读取 Costmap。它只把 <code>Twist.linear.x</code>、<code>Twist.angular.z</code> 映射为 <code>ControlRes.v</code>、<code>ControlRes.w</code>，再发布 <code>/control_to_uart</code>。</p><h2 id="九、遥控模式为什么完全旁路-nav2" tabindex="-1">九、遥控模式为什么完全旁路 Nav2 <a class="header-anchor" href="#九、遥控模式为什么完全旁路-nav2" aria-label="Permalink to &quot;九、遥控模式为什么完全旁路 Nav2&quot;">​</a></h2><h3 id="_9-1-launch-先取得真实终端" tabindex="-1">9.1 Launch 先取得真实终端 <a class="header-anchor" href="#_9-1-launch-先取得真实终端" aria-label="Permalink to &quot;9.1 Launch 先取得真实终端&quot;">​</a></h3><p>如果启动 Shell 有 TTY，Launch 使用 <code>os.ttyname(sys.stdin.fileno())</code> 得到真实 <code>/dev/pts/*</code>；否则回退 <code>/dev/tty</code>。该路径通过 <code>input_device</code> 交给键盘节点。</p><p>这解决了 ROS 2 Launch 子进程仅有伪输出终端、却没有可读标准输入的问题。</p><h3 id="_9-2-wall-timer-是遥控回调入口" tabindex="-1">9.2 Wall Timer 是遥控回调入口 <a class="header-anchor" href="#_9-2-wall-timer-是遥控回调入口" aria-label="Permalink to &quot;9.2 Wall Timer 是遥控回调入口&quot;">​</a></h3><p>键盘节点以默认 <code>50 Hz</code> 执行 Timer 回调，单周期顺序是：</p><ul><li>非阻塞读取全部已到达字符。</li><li>解析 WASD、方向键、Space、X 和 Q。</li><li>判断方向键重复输入是否超时。</li><li>用 steady clock 计算真实 <code>dt</code>。</li><li>更新平滑速度并发布 ControlRes。</li></ul><h3 id="_9-3-松键停车与紧急停车不同" tabindex="-1">9.3 松键停车与紧急停车不同 <a class="header-anchor" href="#_9-3-松键停车与紧急停车不同" aria-label="Permalink to &quot;9.3 松键停车与紧急停车不同&quot;">​</a></h3><p>方向键一段时间没有重复字符后，目标速度归零，实际输出按减速度斜坡平滑下降。前后或左右换向会先减速到零，再向新方向加速。</p><p>Space 与 X 是正常平滑停车；Q 与节点安全收口会立即清零并发布停车。</p><h3 id="_9-4-遥控链没有-service-或-action" tabindex="-1">9.4 遥控链没有 Service 或 Action <a class="header-anchor" href="#_9-4-遥控链没有-service-或-action" aria-label="Permalink to &quot;9.4 遥控链没有 Service 或 Action&quot;">​</a></h3><p>键盘节点没有业务 Action，也没有业务 Service。它的输入是终端字符，输出是 <code>byd_custom_msgs/msg/ControlRes</code>。</p><p>因此遥控模式不能返回“导航成功”，也没有目标、路径、Costmap 恢复或 ETA 概念。</p><p><img src="'+d+'" alt="遥控直达链"></p><h2 id="十、所有业务-service-如何连接" tabindex="-1">十、所有业务 Service 如何连接 <a class="header-anchor" href="#十、所有业务-service-如何连接" aria-label="Permalink to &quot;十、所有业务 Service 如何连接&quot;">​</a></h2><h3 id="_10-1-map-server-的两个地图-service" tabindex="-1">10.1 Map Server 的两个地图 Service <a class="header-anchor" href="#_10-1-map-server-的两个地图-service" aria-label="Permalink to &quot;10.1 Map Server 的两个地图 Service&quot;">​</a></h3><p><code>map_server/map</code> 返回当前 <code>OccupancyGrid</code>；<code>map_server/load_map</code> 在 active 状态下从新 YAML 加载地图，更新内部缓存并重新发布 <code>/map</code>。</p><p>统一 Launch 只启动 Map Server，不启动 Map Saver，因此没有本包运行链中的 <code>save_map</code> 服务端。</p><h3 id="_10-2-双-costmap-的清理-service" tabindex="-1">10.2 双 Costmap 的清理 Service <a class="header-anchor" href="#_10-2-双-costmap-的清理-service" aria-label="Permalink to &quot;10.2 双 Costmap 的清理 Service&quot;">​</a></h3><p>Local 与 Global Costmap 分别提供：</p><ul><li><code>clear_entirely_*</code>：清空非静态区域。</li><li><code>clear_around_*</code>：清理机器人周边区域。</li><li><code>clear_except_*</code>：保留指定区域，其余清理。</li><li><code>get_costmap</code>：返回当前 Costmap。</li></ul><p>Navigator 的恢复链只调用两个 <code>clear_entirely_*</code>。</p><h3 id="_10-3-planner-的-is-path-valid" tabindex="-1">10.3 Planner 的 <code>is_path_valid</code> <a class="header-anchor" href="#_10-3-planner-的-is-path-valid" aria-label="Permalink to &quot;10.3 Planner 的 `is_path_valid`&quot;">​</a></h3><p>Planner Server 提供 <code>is_path_valid</code>，可根据当前 Costmap 检查 Path。当前 Navigator 不调用它；自主模式相信 Planner Result，固定路径则直接交给 Controller 与 Local Costmap 做运行期安全控制。</p><h3 id="_10-4-lifecycle-manager-的管理-service" tabindex="-1">10.4 Lifecycle Manager 的管理 Service <a class="header-anchor" href="#_10-4-lifecycle-manager-的管理-service" aria-label="Permalink to &quot;10.4 Lifecycle Manager 的管理 Service&quot;">​</a></h3><p>两个 Lifecycle Manager 都提供：</p><ul><li><code>&lt;manager_name&gt;/manage_nodes</code>。</li><li><code>&lt;manager_name&gt;/is_active</code>。</li></ul><p><code>manage_nodes</code> 支持 startup、reset、shutdown、pause 和 resume。地图 Manager 只管理 Map Server，规控 Manager 管理五个 Lifecycle 节点。</p><h3 id="_10-5-每个-lifecycle-节点的标准-service" tabindex="-1">10.5 每个 Lifecycle 节点的标准 Service <a class="header-anchor" href="#_10-5-每个-lifecycle-节点的标准-service" aria-label="Permalink to &quot;10.5 每个 Lifecycle 节点的标准 Service&quot;">​</a></h3><p>Planner、Controller、Smoother、Velocity Smoother、Map Server 和 Navigator 都提供 <code>change_state</code>、<code>get_state</code>、可用状态、可用迁移和迁移图查询 Service。</p><p>这些 Service 决定接口是否处于 active，但不承载 Path、速度或导航反馈。</p><h3 id="_10-6-通用参数-service" tabindex="-1">10.6 通用参数 Service <a class="header-anchor" href="#_10-6-通用参数-service" aria-label="Permalink to &quot;10.6 通用参数 Service&quot;">​</a></h3><p>ROS 节点还会自动提供参数查询和设置 Service。它们属于统一控制面，不应与业务 Action 混淆。当前 Navigator 没有动态参数回调，构造和 configure 后修改部分参数并不会同步改变已缓存成员。</p><p><img src="'+n+'" alt="Service 与 Lifecycle 控制面"></p><h2 id="十一、两个定时器如何驱动-看不见的闭环" tabindex="-1">十一、两个定时器如何驱动“看不见的闭环” <a class="header-anchor" href="#十一、两个定时器如何驱动-看不见的闭环" aria-label="Permalink to &quot;十一、两个定时器如何驱动“看不见的闭环”&quot;">​</a></h2><h3 id="_11-1-publishfeedback-以-5-hz-运行" tabindex="-1">11.1 <code>publishFeedback()</code> 以 5 Hz 运行 <a class="header-anchor" href="#_11-1-publishfeedback-以-5-hz-运行" aria-label="Permalink to &quot;11.1 `publishFeedback()` 以 5 Hz 运行&quot;">​</a></h3><p>反馈 Timer 查询当前 <code>map → base_link</code>，计算导航时间，再结合 FollowPath Feedback 中的剩余距离和速度估算 ETA。</p><p>单点与多点 Action 都会收到当前 Pose、导航时间、预计剩余时间、恢复次数和剩余距离；多点任务还会收到剩余 Pose 数。</p><h3 id="_11-2-monitortask-以-200-ms-运行" tabindex="-1">11.2 <code>monitorTask()</code> 以 200 ms 运行 <a class="header-anchor" href="#_11-2-monitortask-以-200-ms-运行" aria-label="Permalink to &quot;11.2 `monitorTask()` 以 200 ms 运行&quot;">​</a></h3><p>监控 Timer 处理外层取消、恢复等待、TF 健康、定位跳变、控制进展、多点通过和周期重规划。它是没有行为树之后的主调度循环。</p><h3 id="_11-3-cancel-不在-action-回调中直接收口" tabindex="-1">11.3 Cancel 不在 Action 回调中直接收口 <a class="header-anchor" href="#_11-3-cancel-不在-action-回调中直接收口" aria-label="Permalink to &quot;11.3 Cancel 不在 Action 回调中直接收口&quot;">​</a></h3><p>Cancel 回调只设置标志。下一次 <code>monitorTask()</code> 调用 <code>cancelTask()</code>，统一取消 Planner、Smoother、Controller 子 Goal，发布停车命令，并根据 Goal Handle 状态返回 canceled 或 aborted。</p><p>这样可以避免在 rclcpp_action 的取消状态迁移中重入复杂任务清理。</p><h2 id="十二、定位与恢复链如何工作" tabindex="-1">十二、定位与恢复链如何工作 <a class="header-anchor" href="#十二、定位与恢复链如何工作" aria-label="Permalink to &quot;十二、定位与恢复链如何工作&quot;">​</a></h2><h3 id="_12-1-定位输入只有-tf" tabindex="-1">12.1 定位输入只有 TF <a class="header-anchor" href="#_12-1-定位输入只有-tf" aria-label="Permalink to &quot;12.1 定位输入只有 TF&quot;">​</a></h3><p>Navigator 通过 TF Buffer 查询 <code>global_frame → robot_base_frame</code>，当前即 <code>map → base_link</code>。它不订阅 AMCL Pose，也不依赖 <code>odom → base_link</code> TF。</p><p>Velocity Smoother 的 <code>/odometry</code> 是速度反馈，不能代替 Navigator 的全局定位 TF。</p><h3 id="_12-2-tf-超时会先停车" tabindex="-1">12.2 TF 超时会先停车 <a class="header-anchor" href="#_12-2-tf-超时会先停车" aria-label="Permalink to &quot;12.2 TF 超时会先停车&quot;">​</a></h3><p>超过 <code>localization_timeout</code> 无法取得 TF 时，系统取消全部子 Goal，发布三次零速度并进入 <code>LOCALIZATION_LOST</code>。</p><p>定位恢复后必须连续稳定 <code>localization_stable_duration</code>，才允许恢复运动；超过恢复总超时则结束任务。</p><h3 id="_12-3-定位跳变会废弃旧控制上下文" tabindex="-1">12.3 定位跳变会废弃旧控制上下文 <a class="header-anchor" href="#_12-3-定位跳变会废弃旧控制上下文" aria-label="Permalink to &quot;12.3 定位跳变会废弃旧控制上下文&quot;">​</a></h3><p>相邻监控周期的平移或旋转跳变超过阈值时，Navigator 取消旧子 Goal、停车并恢复任务。</p><p>自主任务重新规划；固定路径任务重发保存的最新 Path。</p><h3 id="_12-4-恢复只保留清图与等待" tabindex="-1">12.4 恢复只保留清图与等待 <a class="header-anchor" href="#_12-4-恢复只保留清图与等待" aria-label="Permalink to &quot;12.4 恢复只保留清图与等待&quot;">​</a></h3><p>当前包不启动 Behavior Server，也不调用 Spin、BackUp 或 Wait Action。恢复流程是：</p><ul><li>取消在途 Planner、Smoother 和 Controller Goal。</li><li>发布停车命令。</li><li>异步请求清理 Local 与 Global Costmap。</li><li>固定等待 Costmap 更新。</li><li>按任务类型重新规划或重发路径。</li></ul><p>达到最大恢复轮数后，外层 Action 失败。</p><p><img src="'+h+'" alt="监控与恢复状态机"></p><h2 id="十三、topic-数据面如何从地图流到电机" tabindex="-1">十三、Topic 数据面如何从地图流到电机 <a class="header-anchor" href="#十三、topic-数据面如何从地图流到电机" aria-label="Permalink to &quot;十三、Topic 数据面如何从地图流到电机&quot;">​</a></h2><h3 id="_13-1-地图与雷达进入两张-costmap" tabindex="-1">13.1 地图与雷达进入两张 Costmap <a class="header-anchor" href="#_13-1-地图与雷达进入两张-costmap" aria-label="Permalink to &quot;13.1 地图与雷达进入两张 Costmap&quot;">​</a></h3><p>Map Server 发布 <code>/map</code>。Global Costmap 的 Static Layer 消费静态地图，Obstacle Layer 消费雷达；Local Costmap 的 Voxel Layer 消费同一个 LaserScan。两张 Costmap 再分别服务 Planner 与 Controller。</p><h3 id="_13-2-path-有三种来源" tabindex="-1">13.2 Path 有三种来源 <a class="header-anchor" href="#_13-2-path-有三种来源" aria-label="Permalink to &quot;13.2 Path 有三种来源&quot;">​</a></h3><ul><li>自主单点 Planner Result。</li><li>自主多点 Planner Result。</li><li>固定路径 <code>/fixed_path</code>。</li></ul><p>自主 Path 可经过 Smoother；固定 Path 不经过。最终都以 FollowPath Goal 进入 Controller。</p><h3 id="_13-3-twist-有两个层级" tabindex="-1">13.3 Twist 有两个层级 <a class="header-anchor" href="#_13-3-twist-有两个层级" aria-label="Permalink to &quot;13.3 Twist 有两个层级&quot;">​</a></h3><p>Controller 输出的是目标控制命令 <code>cmd_vel_nav</code>。Velocity Smoother 输出的是受实测速度、运动学约束和超时保护处理后的 <code>/cmd_vel</code>。</p><p>不要直接把 Controller 输出误认为底盘最终执行速度。</p><h3 id="_13-4-controlres-是底盘接口" tabindex="-1">13.4 ControlRes 是底盘接口 <a class="header-anchor" href="#_13-4-controlres-是底盘接口" aria-label="Permalink to &quot;13.4 ControlRes 是底盘接口&quot;">​</a></h3><p>导航链通过 <code>controlpub</code> 产生 ControlRes；遥控链直接产生 ControlRes。两条链最终使用同一 <code>/control_to_uart</code>，但由 Launch 保证不会同时存在。</p><h2 id="十四、当前源码中需要警惕的边界" tabindex="-1">十四、当前源码中需要警惕的边界 <a class="header-anchor" href="#十四、当前源码中需要警惕的边界" aria-label="Permalink to &quot;十四、当前源码中需要警惕的边界&quot;">​</a></h2><h3 id="_14-1-cancel-timeout-目前没有生效" tabindex="-1">14.1 <code>cancel_timeout</code> 目前没有生效 <a class="header-anchor" href="#_14-1-cancel-timeout-目前没有生效" aria-label="Permalink to &quot;14.1 `cancel_timeout` 目前没有生效&quot;">​</a></h3><p>参数被声明并读取到成员，但 <code>cancelSubGoals()</code> 只异步调用 <code>async_cancel_goal()</code>，没有按 <code>cancel_timeout_</code> 等待取消确认。</p><p>因此该参数当前不会改变取消耗时，也不能保证旧服务器在超时前已经停止输出。</p><h3 id="_14-2-部分参数缺少统一校验" tabindex="-1">14.2 部分参数缺少统一校验 <a class="header-anchor" href="#_14-2-部分参数缺少统一校验" aria-label="Permalink to &quot;14.2 部分参数缺少统一校验&quot;">​</a></h3><p><code>PlanningModule</code> 校验重规划频率和连续失败上限，<code>ControlModule</code> 校验进展超时，但 <code>feedback_frequency</code> 没有正值检查。设为零会进入定时器周期除零。</p><p>恢复次数、定位超时和跳变阈值也没有在 <code>on_configure()</code> 中统一验证。</p><h3 id="_14-3-action-server-等待不是一个总预算" tabindex="-1">14.3 Action Server 等待不是一个总预算 <a class="header-anchor" href="#_14-3-action-server-等待不是一个总预算" aria-label="Permalink to &quot;14.3 Action Server 等待不是一个总预算&quot;">​</a></h3><p><code>dependenciesReady()</code> 对 Planner 单点、Planner 多点、可选 Smoother 和 Controller 依次使用完整 <code>server_timeout</code>。多个服务器都不可用时，总等待可能接近该参数的四倍。</p><h3 id="_14-4-固定-path-校验失败只发零速" tabindex="-1">14.4 固定 Path 校验失败只发零速 <a class="header-anchor" href="#_14-4-固定-path-校验失败只发零速" aria-label="Permalink to &quot;14.4 固定 Path 校验失败只发零速&quot;">​</a></h3><p>已有固定路径正在 FollowPath 时，新 Path 若无效，回调只调用 <code>stopRobot()</code>，没有取消旧 FollowPath。Controller 后续周期仍可能重新发布速度，覆盖短暂的三帧零指令。</p><p>更严格的安全语义应明确选择“拒绝更新并继续旧路径”，或“取消旧控制并保持停车”，而不是两种状态同时存在。</p><h3 id="_14-5-failtask-没有显式停车" tabindex="-1">14.5 <code>failTask()</code> 没有显式停车 <a class="header-anchor" href="#_14-5-failtask-没有显式停车" aria-label="Permalink to &quot;14.5 `failTask()` 没有显式停车&quot;">​</a></h3><p>失败收口会取消子 Goal 并 abort 外层 Action，但没有直接调用 <code>stopRobot()</code>。最终停车依赖 Controller 对取消的处理，在异步链路中不如主动零速明确。</p><h3 id="_14-6-清图结果没有进入状态判断" tabindex="-1">14.6 清图结果没有进入状态判断 <a class="header-anchor" href="#_14-6-清图结果没有进入状态判断" aria-label="Permalink to &quot;14.6 清图结果没有进入状态判断&quot;">​</a></h3><p>恢复流程只在 Service ready 时异步发送请求，不等待响应，也不检查清图是否成功。无论 Service 未就绪、请求失败还是成功，状态机都会在固定时间后继续恢复。</p><h3 id="_14-7-pose-校验不等于四元数归一化" tabindex="-1">14.7 Pose 校验不等于四元数归一化 <a class="header-anchor" href="#_14-7-pose-校验不等于四元数归一化" aria-label="Permalink to &quot;14.7 Pose 校验不等于四元数归一化&quot;">​</a></h3><p><code>validPose()</code> 只要求四元数范数有限且大于极小值，不要求范数接近一，也不主动归一化自主 Action Goal。固定 Path 经过 TF 变换，自主 Goal 则直接进入 Planner。</p><h3 id="_14-8-rviz-与-composition-都有启动前提" tabindex="-1">14.8 RViz 与 Composition 都有启动前提 <a class="header-anchor" href="#_14-8-rviz-与-composition-都有启动前提" aria-label="Permalink to &quot;14.8 RViz 与 Composition 都有启动前提&quot;">​</a></h3><p>默认 <code>use_rviz=true</code>，关闭 RViz 会触发整个关联 Launch 的 Shutdown。Composition 模式又要求外部容器预先存在。</p><p>这两个行为都不是算法错误，但会直接影响实车部署方式。</p><h2 id="十五、把整套链路压缩成一句话" tabindex="-1">十五、把整套链路压缩成一句话 <a class="header-anchor" href="#十五、把整套链路压缩成一句话" aria-label="Permalink to &quot;十五、把整套链路压缩成一句话&quot;">​</a></h2><p><code>nav2_regulated_modules</code> 的核心不是“再造一个 Nav2”，而是把标准 Nav2 Server 重新组织成三个互斥运行模式：</p><ul><li>遥控模式让终端输入直接拥有底盘。</li><li>自主模式用 Navigate Action 驱动 ComputePath、SmoothPath 和 FollowPath。</li><li>固定路径模式保留局部安全控制，却把全局规划和平滑从业务链中移除。</li></ul><p>Action 承载长任务、反馈与结果，Service 管理地图、Lifecycle 和恢复，Topic 传递地图、传感器、Path、速度与底盘命令，TF 则决定所有路径和状态能否落在同一个坐标世界里。</p><p>真正决定系统是否可靠的，不只是某个 Planner 或 Controller，而是这些接口之间是否保持单一所有权、可追踪回调和明确失败语义。</p>',222)])])}const f=a(s,[["render",p]]);export{g as __pageData,f as default};
